use crate::api::client::ApiClient;
use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::BTreeMap;

const BILLING_UNIT_SECONDS: i64 = 15 * 60;
const MINIMUM_BILLABLE_SECONDS: i64 = 30 * 60;

pub struct InvoiceMonthlyCommand;

/// Apply the invoice rule independently to each stopped entry.
fn invoice_seconds(entry: &TimeEntry) -> i64 {
    let duration = entry.duration.max(0);
    let rounded = (duration / BILLING_UNIT_SECONDS
        + i64::from(duration % BILLING_UNIT_SECONDS != 0))
        * BILLING_UNIT_SECONDS;
    rounded.max(MINIMUM_BILLABLE_SECONDS)
}

fn monthly_totals(entries: &[TimeEntry]) -> BTreeMap<String, i64> {
    let mut totals = BTreeMap::new();
    for entry in entries
        .iter()
        .filter(|entry| entry.billable && entry.stop.is_some() && !entry.is_running())
    {
        let month = entry.start.format("%Y-%m").to_string();
        *totals.entry(month).or_insert(0) += invoice_seconds(entry);
    }
    totals
}

impl InvoiceMonthlyCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client
            .get_time_entries_filtered_minimal(since, until)
            .await?;
        let totals = monthly_totals(&entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = totals.values().sum();
        for (month, seconds) in totals {
            println!("{month}  {seconds}s");
        }
        println!("Total  {total}s");
        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use chrono::{DateTime, Utc};

    fn entry(start: &str, duration: i64, billable: bool, stop: Option<&str>) -> TimeEntry {
        TimeEntry {
            id: 1,
            description: String::new(),
            start: start.parse::<DateTime<Utc>>().unwrap(),
            stop: stop.map(|value| value.parse::<DateTime<Utc>>().unwrap()),
            duration,
            billable,
            ..TimeEntry::default()
        }
    }

    #[test]
    fn applies_rounding_and_minimum_per_entry() {
        let entries = vec![
            entry(
                "2026-01-10T00:00:00Z",
                1,
                true,
                Some("2026-01-10T00:00:01Z"),
            ),
            entry(
                "2026-01-10T00:00:00Z",
                901,
                true,
                Some("2026-01-10T00:15:01Z"),
            ),
        ];
        assert_eq!(monthly_totals(&entries)["2026-01"], 1_800 + 1_800);
    }

    #[test]
    fn groups_by_utc_start_and_excludes_non_billable_or_running_entries() {
        let entries = vec![
            entry(
                "2026-01-31T23:30:00Z",
                1800,
                true,
                Some("2026-02-01T00:00:00Z"),
            ),
            entry(
                "2026-02-01T00:00:00Z",
                1800,
                false,
                Some("2026-02-01T00:30:00Z"),
            ),
            entry("2026-02-01T00:00:00Z", -1, true, None),
        ];
        let totals = monthly_totals(&entries);
        assert_eq!(totals.len(), 1);
        assert_eq!(totals["2026-01"], 1800);
    }
}

